def countDiameterNodes(n, edges):
    if n == 1:
        return 1
    adj = [[] for _ in range(n)]
    for a, b in edges:
        adj[a].append(b)
        adj[b].append(a)
    parent = [-1] * n
    order = [0]
    seen = [False] * n
    seen[0] = True
    for u in order:
        for v in adj[u]:
            if not seen[v]:
                seen[v] = True
                parent[v] = u
                order.append(v)
    down = [0] * n
    top1 = [0] * n  # two largest child branches (down[c] + 1) of each node
    top2 = [0] * n
    for u in reversed(order):
        p = parent[u]
        if p >= 0:
            b = down[u] + 1
            if b > top1[p]:
                top2[p] = top1[p]
                top1[p] = b
            elif b > top2[p]:
                top2[p] = b
            down[p] = top1[p]
    up = [0] * n
    for u in order:
        p = parent[u]
        if p < 0:
            continue
        other = top2[p] if down[u] + 1 == top1[p] else top1[p]
        up[u] = 1 + max(up[p], other)
    through = [0] * n
    for v in range(n):
        a, b = top1[v], top2[v]
        if v != 0:
            x = up[v]
            if x > a:
                a, b = x, a
            elif x > b:
                b = x
        through[v] = a + b
    best = max(through)
    return sum(1 for x in through if x == best)
